 93	const DIRECTIONS = [
 94	  [1, 0],
 95	  [1, 1],
 96	  [0, 1],
 97	  [-1, 1],
 98	  [-1, 0],
 99	  [-1, -1],
100	  [0, -1],
101	  [1, -1],
102	] as const;
